    const c_cam_3 = ui.must(await ui.addClaim(pg_vic, p_cam, {"amount": "20.00", "date": "2026-03-05", "note": "n"}));
    await ui.setToday(pg_vic, "2026-05-19");
    expect(await ui.claimAction(pg_vic, c_cam_2, "open")).toBe(true);
    await ui.refresh(pg_vic);
    await expect(pg_vic.getByTestId("sheet-archived")).toHaveText("no");
    await expect(pg_vic.getByTestId("sheet-asof")).toHaveText("");
    await expect(pg_vic.getByTestId("sheet-parent")).toHaveText(`${sheet}-p`);

