package net.officefloor.hq.app.pool;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.crew.CrewRepository;
import net.officefloor.hq.app.history.HistoryService;
import net.officefloor.hq.app.period.Period;
import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

@Service
public class PoolService {

    /** A pool with its members, in the order they were added. */
    public record PoolWithMembers(Pool pool, List<PoolMember> members) {
    }

    /** A period and the sheet as it stood at the end of its to-date. */
    public record PeriodThen(Period period, HistoryService.AsOf then) {
    }

    private final PoolRepository pools;
    private final PoolMemberRepository members;
    private final PersonRepository people;
    private final CrewRepository crews;
    private final SheetService sheets;
    private final PeriodRepository periods;
    private final HistoryService history;
    private final Audit audit;

    public PoolService(PoolRepository pools, PoolMemberRepository members, PersonRepository people,
            CrewRepository crews, SheetService sheets, PeriodRepository periods, HistoryService history, Audit audit) {
        this.pools = pools;
        this.members = members;
        this.people = people;
        this.crews = crews;
        this.sheets = sheets;
        this.periods = periods;
        this.history = history;
        this.audit = audit;
    }

    /** The sheet's pools in the order they were added, each with its members. */
    @Transactional(readOnly = true)
    public List<PoolWithMembers> list(String sheetId) {
        List<Pool> all = pools.findBySheetIdOrderByIdAsc(sheetId);
        Map<Long, List<PoolMember>> byPool = members.findByPoolIdInOrderByIdAsc(all.stream().map(Pool::getId).toList())
                .stream().collect(Collectors.groupingBy(PoolMember::getPoolId));
        return all.stream().map(p -> new PoolWithMembers(p, byPool.getOrDefault(p.getId(), List.of()))).toList();
    }

    /** Each of the sheet's periods (by from-date) whose to-date is on or before the day (the sheet's
     *  today when none is given; the periods then as they stood at the end of it), with the sheet as
     *  it stood at the end of that to-date. */
    @Transactional(readOnly = true)
    public List<PeriodThen> history(String sheetId, LocalDate asOf) {
        LocalDate today = asOf != null ? asOf : sheets.today(sheetId);
        List<Period> all = asOf != null
                ? history.asOf(sheetId, asOf).periods().values().stream()
                        .sorted(Comparator.comparing(Period::getFrom)).toList()
                : periods.findBySheetIdOrderByFromAsc(sheetId);
        return all.stream().filter(p -> !p.getTo().isAfter(today))
                .map(p -> new PeriodThen(p, history.asOf(sheetId, p.getTo()))).toList();
    }

    /** Add a pool to the sheet, the sheet created first if it was never loaded; refused (409) when
     *  the sheet has a pool or a crew (a crew is a pool too) of the name already. */
    @Transactional
    public Pool add(String sheetId, String user, String name) {
        sheets.load(sheetId, user);
        sheets.lock(sheetId);
        if (pools.findBySheetIdAndNameIgnoreCase(sheetId, name).isPresent()) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "The sheet has a pool of that name");
        }
        if (crews.findBySheetIdAndNameIgnoreCase(sheetId, name).isPresent()) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "The sheet has a crew of that name");
        }
        Pool pool = pools.saveAndFlush(new Pool(sheetId, name));
        audit.recordOnCommit("POOL_ADDED sheet=" + sheetId + " by=" + user + " name=" + name);
        return pool;
    }

    /** Add a person of the sheet to a pool with a share and optional dates; refused (404) for a pool
     *  or person not on the sheet, (409) when the person is in the pool already. */
    @Transactional
    public PoolMember addMember(String sheetId, String user, String poolName, long personId, BigDecimal share,
            LocalDate from, LocalDate to) {
        sheets.lock(sheetId);
        Pool pool = pools.findBySheetIdAndNameIgnoreCase(sheetId, poolName)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such pool"));
        Person person = people.findByIdAndSheetId(personId, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
        if (members.existsByPoolIdAndPersonId(pool.getId(), person.getId())) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "The person is in the pool already");
        }
        PoolMember member = new PoolMember(pool.getId(), person.getId(), share);
        member.setDates(from, to);
        member = members.saveAndFlush(member);
        audit.recordOnCommit("POOL_MEMBER_ADDED sheet=" + sheetId + " by=" + user + " pool=" + pool.getName()
                + " name=" + person.getName() + " share=" + share.setScale(2).toPlainString() + dates(from, to));
        return member;
    }

    /** The membership's dates as the audit records them: from=<date> and to=<date>, each when given. */
    private static String dates(LocalDate from, LocalDate to) {
        return (from == null ? "" : " from=" + from) + (to == null ? "" : " to=" + to);
    }

    /** The deepest a chain of pools may be, counting the pool at its top. */
    static final int MAX_DEPTH = 3;

    /** Add another pool of the sheet to a pool with a share; refused (404) for a pool not on the
     *  sheet, (409) when the member pool is a member of a pool already, (422) when the pool would
     *  contain itself through any chain or the chain of pools would be more than three deep. */
    @Transactional
    public PoolMember addPoolMember(String sheetId, String user, String poolName, String memberName, BigDecimal share,
            LocalDate from, LocalDate to) {
        sheets.lock(sheetId);
        Pool pool = pools.findBySheetIdAndNameIgnoreCase(sheetId, poolName)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such pool"));
        Pool memberPool = pools.findBySheetIdAndNameIgnoreCase(sheetId, memberName)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such pool"));
        if (members.findByMemberPoolId(memberPool.getId()).isPresent()) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "The pool is a member of a pool already");
        }
        // the pool and the pools above it
        List<Long> above = new ArrayList<>();
        for (Long id = pool.getId(); id != null;
                id = members.findByMemberPoolId(id).map(PoolMember::getPoolId).orElse(null)) {
            above.add(id);
        }
        if (above.contains(memberPool.getId())) {
            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT, "A pool cannot contain itself");
        }
        if (above.size() + height(memberPool.getId()) > MAX_DEPTH) {
            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
                    "A chain of pools is at most " + MAX_DEPTH + " deep");
        }
        PoolMember member = PoolMember.ofPool(pool.getId(), memberPool.getId(), share);
        member.setDates(from, to);
        member = members.saveAndFlush(member);
        audit.recordOnCommit("POOL_MEMBER_ADDED sheet=" + sheetId + " by=" + user + " pool=" + pool.getName()
                + " name=" + memberPool.getName() + " share=" + share.setScale(2).toPlainString() + dates(from, to));
        return member;
    }

    /** How deep the chain of pools from this one down is, counting this one. */
    private int height(Long poolId) {
        int below = 0;
        for (PoolMember m : members.findByPoolIdInOrderByIdAsc(List.of(poolId))) {
            if (m.getMemberPoolId() != null) {
                below = Math.max(below, height(m.getMemberPoolId()));
            }
        }
        return 1 + below;
    }
}
package net.officefloor.hq.app.pool;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;
import net.officefloor.hq.app.crew.CrewController;
import net.officefloor.hq.app.history.AsOfGuard;
import net.officefloor.hq.app.history.HistoryService;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.session.CurrentUser;
import org.springframework.format.annotation.DateTimeFormat;
import org.springframework.http.HttpStatus;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;
import org.springframework.web.server.ResponseStatusException;

@RestController
@RequestMapping("/api/sheets/{sheetId}/pools")
@Validated
public class PoolController {

    /** A member as the screen shows it: the person's id, or the member pool's name, and the share
     *  with two decimals, and the membership's from- and to-date (yyyy-mm-dd, null when not given). */
    public record MemberView(Long personId, String pool, String share, String from, String to) {
        static MemberView of(PoolMember m, Map<Long, String> poolNames) {
            return new MemberView(m.getPersonId(),
                    m.getMemberPoolId() == null ? null : poolNames.get(m.getMemberPoolId()),
                    m.getShare().setScale(2).toPlainString(),
                    m.getFromDate() == null ? null : m.getFromDate().toString(),
                    m.getToDate() == null ? null : m.getToDate().toString());
        }
    }

    /** A pool as the screen shows it: its name and its members in the order they were added. */
    public record PoolView(String name, List<MemberView> members) {
        static PoolView of(PoolService.PoolWithMembers p, Map<Long, String> poolNames) {
            return new PoolView(p.pool().getName(),
                    p.members().stream().map(m -> MemberView.of(m, poolNames)).toList());
        }
    }

    /** A hold as the screen reads it: its from- and to-date (yyyy-mm-dd, the to-date null when open). */
    public record HoldView(String from, String to) {
    }

    /** A person as a period's cuts need them: their id, the date they are retired from (null when
     *  not retired) and their holds. */
    public record PersonThen(long id, String retiredFrom, List<HoldView> holds) {
        static PersonThen of(long id, Person p) {
            return new PersonThen(id, p.getRetiredFrom() == null ? null : p.getRetiredFrom().toString(),
                    p.getHolds().stream()
                            .map(h -> new HoldView(h.from().toString(), h.to() == null ? null : h.to().toString()))
                            .toList());
        }
    }

    /** A period whose to-date has come, with what its cuts are worked from as they stood at the end
     *  of it: the period's name and to-date (the day the cuts are taken on), the pot then (two
     *  decimals, null when none), the pools and crews then and the people then. */
    public record PeriodCutsView(String period, String to, String pot, List<PoolView> pools,
            List<CrewController.CrewView> crews, List<PersonThen> people) {
        static PeriodCutsView of(PoolService.PeriodThen p) {
            HistoryService.AsOf then = p.then();
            Map<Long, String> poolNames = then.pools().entrySet().stream()
                    .collect(Collectors.toMap(Map.Entry::getKey, e -> e.getValue().name()));
            List<PoolView> pools = then.pools().entrySet().stream()
                    .map(e -> new PoolView(e.getValue().name(), then.poolMembers().values().stream()
                            .filter(m -> m.poolId() == e.getKey())
                            .map(m -> new MemberView(m.personId(),
                                    m.memberPoolId() == null ? null : poolNames.get(m.memberPoolId()),
                                    m.share().setScale(2).toPlainString(),
                                    m.from() == null ? null : m.from().toString(),
                                    m.to() == null ? null : m.to().toString()))
                            .toList()))
                    .toList();
            List<CrewController.CrewView> crews = then.crews().entrySet().stream()
                    .map(e -> new CrewController.CrewView(e.getValue().name(), e.getValue().leadId(),
                            then.crewMembers().values().stream().filter(m -> m.crewId() == e.getKey())
                                    .map(HistoryService.CrewMemberState::personId).toList()))
                    .toList();
            return new PeriodCutsView(p.period().getName(), p.period().getTo().toString(),
                    then.sheet().getPot() == null ? null : then.sheet().getPot().setScale(2).toPlainString(),
                    pools, crews,
                    then.people().entrySet().stream().map(e -> PersonThen.of(e.getKey(), e.getValue())).toList());
        }
    }

    /** A pool as the form submits it: a name (not blank). */
    public record PoolForm(@NotBlank @Size(max = 200) String name) {
    }

    /** A member as the pool's row submits it: the pool, a person or another pool of the sheet
     *  (exactly one), and a share percent with up to two decimals, more than 0.00 and at most
     *  100.00, and an optional from- and to-date (yyyy-mm-dd, blank for none). */
    public record MemberForm(
            @NotBlank @Size(max = 200) String pool,
            Long personId,
            @Size(max = 200) String memberPool,
            @NotNull @Pattern(regexp = "\\s*\\d{1,3}(\\.\\d{1,2})?\\s*") String share,
            @Pattern(regexp = "\\s*(\\d{4}-\\d{2}-\\d{2})?\\s*") String from,
            @Pattern(regexp = "\\s*(\\d{4}-\\d{2}-\\d{2})?\\s*") String to) {
    }

    private final PoolService service;

    public PoolController(PoolService service) {
        this.service = service;
    }

    @GetMapping
    public List<PoolView> list(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "\\S+") String sheetId,
            @RequestHeader(CurrentUser.HEADER) @NotBlank @Size(max = 100) String user) {
        List<PoolService.PoolWithMembers> all = service.list(sheetId);
        Map<Long, String> poolNames = all.stream()
                .collect(Collectors.toMap(p -> p.pool().getId(), p -> p.pool().getName()));
        return all.stream().map(p -> PoolView.of(p, poolNames)).toList();
    }

    /** Each period whose to-date is on or before the sheet's today (or the as-of date), by from-date,
     *  with the pools, crews, pot and people as they stood at the end of its to-date. */
    @GetMapping("/history")
    public List<PeriodCutsView> history(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "\\S+") String sheetId,
            @RequestHeader(CurrentUser.HEADER) @NotBlank @Size(max = 100) String user,
            @RequestHeader(value = AsOfGuard.HEADER, required = false) @DateTimeFormat(iso = DateTimeFormat.ISO.DATE) LocalDate asOf) {
        return service.history(sheetId, asOf).stream().map(PeriodCutsView::of).toList();
    }

    /** Add a pool; resolves to the sheet's pools with it. */
    @PostMapping
    public List<PoolView> add(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "\\S+") String sheetId,
            @RequestHeader(CurrentUser.HEADER) @NotBlank @Size(max = 100) String user,
            @Valid @RequestBody PoolForm body) {
        service.add(sheetId, user.trim(), body.name().trim());
        return list(sheetId, user);
    }

    /** Add a member to a pool; resolves to the sheet's pools with it. */
    @PostMapping("/members")
    public List<PoolView> addMember(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "\\S+") String sheetId,
            @RequestHeader(CurrentUser.HEADER) @NotBlank @Size(max = 100) String user,
            @Valid @RequestBody MemberForm body) {
        boolean isPool = body.memberPool() != null && !body.memberPool().isBlank();
        if (isPool == (body.personId() != null)) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "Choose a person or a pool");
        }
        BigDecimal share = share(body.share());
        LocalDate from = date(body.from());
        LocalDate to = date(body.to());
        if (from != null && to != null && to.isBefore(from)) {
            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT, "The to-date is before the from-date");
        }
        if (isPool) {
            service.addPoolMember(sheetId, user.trim(), body.pool().trim(), body.memberPool().trim(), share, from, to);
        } else {
            service.addMember(sheetId, user.trim(), body.pool().trim(), body.personId(), share, from, to);
        }
        return list(sheetId, user);
    }

    /** A date, null when blank; refused (400) when not a real date. */
    private static LocalDate date(String text) {
        if (text == null || text.isBlank()) return null;
        try {
            return LocalDate.parse(text.trim());
        } catch (DateTimeParseException e) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "Not a date");
        }
    }

    /** The share, refused (400) unless more than 0.00 and at most 100.00. */
    private static BigDecimal share(String text) {
        BigDecimal share = new BigDecimal(text.trim()).setScale(2);
        if (share.signum() <= 0 || share.compareTo(new BigDecimal("100.00")) > 0) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "A share is more than 0.00 and at most 100.00");
        }
        return share;
    }
}
package net.officefloor.hq.app.pool;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.EntityListeners;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import java.math.BigDecimal;
import java.time.LocalDate;
import net.officefloor.hq.app.history.HistoryListener;

/** A person, or another pool, in a pool with their share percent (two decimals, more than 0.00,
 *  at most 100.00): exactly one of the person and the member pool is set. The membership may carry
 *  a from-date and a to-date (both inclusive, either optional). */
@Entity
@EntityListeners(HistoryListener.class)
@Table(name = "pool_member")
public class PoolMember {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "pool_id", nullable = false)
    private Long poolId;

    @Column(name = "person_id")
    private Long personId;

    @Column(name = "member_pool_id")
    private Long memberPoolId;

    @Column(name = "share", nullable = false, precision = 5, scale = 2)
    private BigDecimal share;

    @Column(name = "from_date")
    private LocalDate fromDate;

    @Column(name = "to_date")
    private LocalDate toDate;

    protected PoolMember() {
    }

    public PoolMember(Long poolId, Long personId, BigDecimal share) {
        this.poolId = poolId;
        this.personId = personId;
        this.share = share;
    }

    /** A pool as a member of another pool, with a share. */
    public static PoolMember ofPool(Long poolId, Long memberPoolId, BigDecimal share) {
        PoolMember member = new PoolMember(poolId, null, share);
        member.memberPoolId = memberPoolId;
        return member;
    }

    public Long getId() {
        return id;
    }

    public Long getPoolId() {
        return poolId;
    }

    public Long getPersonId() {
        return personId;
    }

    /** The pool that is this member, null for a person. */
    public Long getMemberPoolId() {
        return memberPoolId;
    }

    public BigDecimal getShare() {
        return share;
    }

    /** Move the membership to another person. */
    public void setPersonId(Long personId) {
        this.personId = personId;
    }

    public void setShare(BigDecimal share) {
        this.share = share;
    }

    /** The first day of the membership, null when it has no start. */
    public LocalDate getFromDate() {
        return fromDate;
    }

    /** The last day of the membership, null when it has no end. */
    public LocalDate getToDate() {
        return toDate;
    }

    public void setDates(LocalDate fromDate, LocalDate toDate) {
        this.fromDate = fromDate;
        this.toDate = toDate;
    }
}
