export class PoolRow {
  private readonly session = inject(Session);
  private readonly api = inject(PoolsApi);

  readonly pool = input.required<Pool>();
  /** The people on the sheet (retired ones too). */
  readonly people = input.required<Person[]>();
  /** The sheet's pools (not its crews), any of which may be chosen as a member. */
  readonly pools = input.required<Pool[]>();
  /** Each member's cut of this pool's pot, by member key. */
  readonly cuts = input.required<Map<string, string>>();
  /** Each ended period's cuts of this pool, as they stood at the end of the period. */
  readonly periodCuts = input.required<PeriodCuts[]>();
  /** The sheet's pools after a member was added. */
  readonly saved = output<Pool[]>();

  protected readonly error = signal<string | null>(null);
  private saving = false;

  protected readonly form = new FormGroup({
    member: new FormControl('', { nonNullable: true }),
    share: new FormControl('', { nonNullable: true }),
    from: new FormControl('', { nonNullable: true }),
    to: new FormControl('', { nonNullable: true }),
  });

  private readonly byId = computed(() => new Map(this.people().map((p) => [p.id, p])));
  /** The members' shares added up (a retired member's too), one whose dates do not include the
   *  sheet's today counting 0.00. */
  private readonly totalCents = computed(() =>
    memberShares(this.pool(), this.session.today()).reduce((sum, c) => sum + c, 0));
  protected readonly totalShare = computed(() => money(this.totalCents()));
  /** Balanced when the shares total exactly 100.00. */
  protected readonly balanced = computed(() => this.totalCents() === 10000);

  constructor() {
    this.form.valueChanges.subscribe(() => this.error.set(null));
  }

  protected key(m: PoolMember): string {
    return memberKey(m);
  }

  protected nameOf(m: PoolMember): string {
    return m.pool !== null ? `pool:${m.pool}` : (this.byId().get(m.personId ?? -1)?.name ?? '');
  }

  protected retired(personId: number): boolean {
    return (this.byId().get(personId)?.retiredFrom ?? null) !== null;
  }

  protected async add(): Promise<void> {
    if (this.saving) return;
    this.error.set(null);
    const sheetId = this.session.sheetId();
    if (!sheetId) return;
    const value = this.form.getRawValue();
    const share = value.share.trim();
    let member: { personId: number } | { memberPool: string };
    if (value.member.startsWith('pool:')) {
      const memberPool = value.member.slice('pool:'.length);
      if (!this.pools().some((p) => p.name === memberPool)) {
        this.error.set('Choose a person or pool to add to the pool.');
        return;
      }
      member = { memberPool };
    } else {
      const personId = Number(value.member);
      if (value.member === '' || !this.byId().has(personId)) {
        this.error.set('Choose a person or pool to add to the pool.');
        return;
      }
      if (this.pool().members.some((m) => m.personId === personId)) {
        this.error.set('That person is in the pool already.');
        return;
      }
      member = { personId };
    }
    if (!SHARE_PATTERN.test(share) || cents(share) <= 0 || cents(share) > 10000) {
      this.error.set('Enter a share more than 0.00 and at most 100.00, with up to two decimals.');
      return;
    }
    const from = value.from.trim();
    const to = value.to.trim();
    if ((from !== '' && !MEMBER_DATE_PATTERN.test(from)) || (to !== '' && !MEMBER_DATE_PATTERN.test(to))) {
      this.error.set('Enter the from- and to-date as yyyy-mm-dd, or leave them blank.');
      return;
    }
    if (from !== '' && to !== '' && to < from) {
      this.error.set('The to-date cannot be before the from-date.');
      return;
    }
    this.saving = true;
    try {
      const pools = await this.api.addMember(sheetId, this.pool().name, member, share, from, to);
      if (this.session.sheetId() === sheetId) this.saved.emit(pools);
      this.form.reset({ member: '', share: '', from: '', to: '' }, { emitEvent: false });
    } catch (e) {
      this.error.set(memberError(e));
    } finally {
      this.saving = false;
    }
  }
}

// The sheet's pools, in the order they were added, and the form that adds one.
@Component({
  selector: 'app-pools',
  imports: [ReactiveFormsModule, PoolRow],
  template: `
    <section aria-labelledby="pools-heading">
      <h2 id="pools-heading">Pools</h2>
      <form [formGroup]="form" (ngSubmit)="add()" aria-label="Add a pool">
        <label for="pool-form-name">Name</label>
        <input id="pool-form-name" data-testid="pool-form-name" formControlName="name" autocomplete="off" />
        <button type="submit" data-testid="pool-form-submit">Add pool</button>
        @if (error(); as err) {
          <p role="alert" data-testid="pool-form-error">{{ err }}</p>
        }
      </form>
      <button type="button" data-testid="export-pools" (click)="exportCsv()">Export pools (CSV)</button>
      <ul aria-label="Pools" data-testid="pools-list">
        @for (p of allPools(); track p.name) {
          <li appPoolRow [pool]="p" [people]="people()" [pools]="pools()" [cuts]="cuts().get(p.name) ?? noCuts"
            [periodCuts]="periodCuts().get(p.name) ?? noPeriodCuts"
            (saved)="taken($event)"></li>
        }
      </ul>
    </section>
  `,
})
export class Pools {
  private readonly session = inject(Session);
  private readonly document = inject(DOCUMENT);
  private readonly api = inject(PoolsApi);

  /** The people on the sheet (retired ones too). */
  readonly people = input.required<Person[]>();
  /** The sheet's crews, each also a pool under its name. */
  readonly crews = input.required<Crew[]>();
  /** Each person's cut total in cents, by person id: their cuts across every pool they are a
   *  member of, added up (a pool that shows no cuts adds nothing). */
  readonly cutTotals = output<Map<number, number>>();

  protected readonly pools = signal<Pool[]>([]);
  /** The sheet's pools, then its crews as pools, each in the order they were added. */
  protected readonly allPools = computed(() => [...this.pools(), ...this.crews().map(crewPool)]);
  protected readonly error = signal<string | null>(null);
  protected readonly noCuts = new Map<string, string>();
  /** Each pool's members' cuts, by pool name: a pool that is a member of none cuts the sheet's
   *  pot; a pool that is a member of another has no pot of its own but its cut in the pool above
   *  (none when that pool has no cuts). */
  protected readonly cuts = computed(() => {
    const today = this.session.today();
    const people = this.people();
    const retiredIds = new Set(people.filter((p) => (p.retiredFrom ?? null) !== null).map((p) => p.id));
    const heldIds = new Set(people.filter((p) => today !== null && heldOn(p.holds, today)).map((p) => p.id));
    return allCuts(this.allPools(), this.session.pot(), retiredIds, heldIds, today);
  });
  /** Each period whose to-date is on or before the sheet's today, as it all stood at the end of it. */
  private readonly history = signal<PeriodThen[]>([]);
  /** Each such period's cuts by pool name, worked as the cuts are with the pools, crews, pot and
   *  people as they stood at the end of the period and its to-date as the sheet's today. */
  private readonly historyCuts = computed(() => this.history().map((h) => {
    const retiredIds = new Set(h.people.filter((p) => p.retiredFrom !== null).map((p) => p.id));
    const heldIds = new Set(h.people.filter((p) => heldOn(p.holds, h.to)).map((p) => p.id));
    const pools = [...h.pools, ...h.crews.map(crewPool)];
    return { period: h.period, cuts: allCuts(pools, h.pot, retiredIds, heldIds, h.to) };
  }));
  /** Each pool's ended periods' cuts, by pool name (a pool that did not exist then has none). */
  protected readonly periodCuts = computed(() => new Map(this.allPools().map((p) =>
    [p.name, this.historyCuts().map((h): PeriodCuts => ({ period: h.period, cuts: h.cuts.get(p.name) ?? this.noCuts }))])));
  protected readonly noPeriodCuts: PeriodCuts[] = [];
  private saving = false;
  /** Guards against a slower, older read landing over a newer one. */
  private readSeq = 0;

  protected readonly form = new FormGroup({
    name: new FormControl('', { nonNullable: true }),
  });

  constructor() {
    this.form.valueChanges.subscribe(() => this.error.set(null));
    effect(() => {
      const totals = new Map<number, number>();
      const cuts = this.cuts();
      for (const p of this.allPools()) {
        const poolCuts = cuts.get(p.name);
        for (const m of p.members) {
          const cut = poolCuts?.get(memberKey(m));
          if (m.personId !== null && cut !== undefined) totals.set(m.personId, (totals.get(m.personId) ?? 0) + cents(cut));
        }
      }
      untracked(() => this.cutTotals.emit(totals));
    });
    effect(() => {
      const id = this.session.sheetId();
      this.session.loads();
      this.session.today();
      untracked(() => {
        this.history.set([]);
        if (id) void this.readHistory(id);
      });
    });
    effect(() => {
      const id = this.session.sheetId();
      this.session.loads();
      untracked(() => {
        this.pools.set([]);
        this.error.set(null);
        this.form.reset({ name: '' }, { emitEvent: false });
        if (id) void this.read(id);
      });
    });
  }

  /** Download the pools as CSV: pools in the order added, each one's members in the order added,
   *  a pool member as pool:<name>, the cut as shown (empty when none). */
  protected exportCsv(): void {
    const byId = new Map(this.people().map((p) => [p.id, p.name]));
    const cuts = this.cuts();
    const lines = [csvLine(['pool', 'member', 'share', 'cut'])];
    for (const p of this.allPools()) {
      for (const m of p.members) {
        const member = m.pool !== null ? `pool:${m.pool}` : (byId.get(m.personId ?? -1) ?? '');
        lines.push(csvLine([p.name, member, m.share, cuts.get(p.name)?.get(memberKey(m)) ?? '']));
      }
    }
    const url = URL.createObjectURL(new Blob([lines.join('')], { type: 'text/csv' }));
    const link = this.document.createElement('a');
    link.href = url;
    link.download = `pools-${this.session.sheetId()}.csv`;
    link.click();
    setTimeout(() => URL.revokeObjectURL(url));
  }

  protected taken(pools: Pool[]): void {
    this.readSeq++;
    this.pools.set(pools);
    const id = this.session.sheetId();
    if (id) void this.readHistory(id);
  }

  protected async add(): Promise<void> {
    if (this.saving) return;
    this.error.set(null);
    const sheetId = this.session.sheetId();
    if (!sheetId) return;
    const name = this.form.getRawValue().name.trim();
    if (name === '') {
      this.error.set('Enter a name for the pool.');
      return;
    }
    if (this.allPools().some((p) => p.name.toLowerCase() === name.toLowerCase())) {
      this.error.set('The sheet has a pool or a crew of that name already.');
      return;
    }
    this.saving = true;
    try {
      const pools = await this.api.add(sheetId, name);
      if (this.session.sheetId() === sheetId) this.taken(pools);
      this.form.reset({ name: '' }, { emitEvent: false });
    } catch (e) {
      this.error.set(poolError(e));
    } finally {
      this.saving = false;
    }
  }

  /** Guards against a slower, older read of the history landing over a newer one. */
  private historySeq = 0;

  private async readHistory(sheetId: string): Promise<void> {
    const seq = ++this.historySeq;
    try {
      const history = await this.api.history(sheetId);
      if (seq === this.historySeq && this.session.sheetId() === sheetId) this.history.set(history);
    } catch {
      if (seq === this.historySeq) this.error.set('Something went wrong loading pools; try again.');
    }
  }

  private async read(sheetId: string): Promise<void> {
    const seq = ++this.readSeq;
    try {
      const pools = await this.api.list(sheetId);
      if (seq === this.readSeq && this.session.sheetId() === sheetId) this.pools.set(pools);
    } catch {
      if (seq === this.readSeq) this.error.set('Something went wrong loading pools; try again.');
    }
  }
}
import { HttpClient, HttpErrorResponse } from '@angular/common/http';
import { Injectable, inject } from '@angular/core';
import { firstValueFrom } from 'rxjs';
import { Session, otherError } from '../../core/session';
import { money } from '../claims/claims-api';
import { type Crew, crewIds } from '../crews/crews-api';
import { type Hold, patronShares } from '../people/people-api';

/** A share percent: up to two decimals (more than 0.00 and at most 100.00 is checked apart). */
export const SHARE_PATTERN = /^\d{1,3}(\.\d{1,2})?$/;

/** A from- or to-date of a membership: yyyy-mm-dd. */
export const MEMBER_DATE_PATTERN = /^\d{4}-\d{2}-\d{2}$/;

/** A person, or another pool of the sheet, in a pool with their share percent (two decimals):
 *  exactly one of personId and pool is set. The membership may carry a from- and a to-date
 *  (yyyy-mm-dd, both inclusive, null when not given). */
export interface PoolMember {
  personId: number | null;
  pool: string | null;
  share: string;
  from: string | null;
  to: string | null;
}

/** Whether the membership's dates include the day (yyyy-mm-dd): a member outside them is left out
 *  of the pool entirely. With no day known, every member is in. */
export function memberOn(m: PoolMember, day: string | null): boolean {
  if (day === null) return true;
  return (m.from === null || m.from <= day) && (m.to === null || day <= m.to);
}

/** A member's key in its row's data-testid: the person's id, or pool-<name>. */
export function memberKey(m: PoolMember): string {
  return m.pool !== null ? `pool-${m.pool}` : String(m.personId);
}

/** A pool on the sheet: its name and its members, in the order they were added. A crew is a pool
 *  too (crew set): its lead and its members at equal shares, kept by the crew itself. */
export interface Pool {
  name: string;
  members: PoolMember[];
  crew?: boolean;
}

/** A crew as a pool under its name: its lead, then its members, at equal shares (100.00 split as
 *  patrons' shares are, the remainder on the lead, or on the first member when it has no lead). */
export function crewPool(crew: Crew): Pool {
  const ids = crewIds(crew);
  const shares = patronShares(ids.length);
  return {
    name: crew.name,
    members: ids.map((personId, i) => ({ personId, pool: null, share: money(shares[i]), from: null, to: null })),
    crew: true,
  };
}

/** A person as a period's cuts need them: their id, the date they are retired from (null when not
 *  retired) and their holds. */
export interface PersonThen {
  id: number;
  retiredFrom: string | null;
  holds: Hold[];
}

/** A period whose to-date is on or before the sheet's today, with what its cuts are worked from as
 *  it all stood at the end of that to-date (the day the cuts are taken on): the pot then (null when
 *  none), the pools and crews then, and the people then. */
export interface PeriodThen {
  period: string;
  to: string;
  pot: string | null;
  pools: Pool[];
  crews: Crew[];
  people: PersonThen[];
}

@Injectable({ providedIn: 'root' })
export class PoolsApi {
  private readonly http = inject(HttpClient);
  private readonly session = inject(Session);

  /** The sheet's pools, in the order they were added. */
  list(sheetId: string): Promise<Pool[]> {
    return firstValueFrom(this.http.get<Pool[]>(this.url(sheetId), { headers: this.headers() }));
  }

  /** Each period whose to-date is on or before the sheet's today, by from-date, as it all stood at
   *  the end of its to-date. */
  history(sheetId: string): Promise<PeriodThen[]> {
    return firstValueFrom(this.http.get<PeriodThen[]>(`${this.url(sheetId)}/history`, { headers: this.headers() }));
  }

  /** Add a pool; resolves to the sheet's pools with it. */
  add(sheetId: string, name: string): Promise<Pool[]> {
    return firstValueFrom(this.http.post<Pool[]>(this.url(sheetId), { name }, { headers: this.headers() }));
  }

  /** Add a person, or another pool, to a pool with a share; resolves to the sheet's pools with them. */
  addMember(sheetId: string, pool: string, member: { personId: number } | { memberPool: string }, share: string,
    from: string, to: string): Promise<Pool[]> {
    return firstValueFrom(
      this.http.post<Pool[]>(`${this.url(sheetId)}/members`, { pool, ...member, share, from, to }, { headers: this.headers() }),
    );
  }

  private url(sheetId: string): string {
    return `/api/sheets/${encodeURIComponent(sheetId)}/pools`;
  }

  private headers(): Record<string, string> {
    return { 'X-User': this.session.user() ?? '' };
  }
}

export function poolError(e: unknown): string {
  if (e instanceof HttpErrorResponse && e.status === 400) return 'Enter a name for the pool.';
  if (e instanceof HttpErrorResponse && e.status === 409) return 'The sheet has a pool or a crew of that name already.';
  return otherError(e);
}

export function memberError(e: unknown): string {
  if (e instanceof HttpErrorResponse && e.status === 400) return 'Enter a share more than 0.00 and at most 100.00, with up to two decimals, and dates as yyyy-mm-dd.';
  if (e instanceof HttpErrorResponse && e.status === 409) return 'That person is in the pool already, or that pool is a member of a pool already.';
  if (e instanceof HttpErrorResponse && e.status === 422) return 'A pool cannot contain itself, a chain of pools is at most three deep, and a to-date is not before the from-date.';
  if (e instanceof HttpErrorResponse && e.status === 404) return 'That pool or person is no longer on the sheet; load the sheet again.';
  return otherError(e);
}

